static void Set(UnityEngine.Object target,string name,object value){var so=new SerializedObject(target);var p=so.FindProperty(name);if(p==null)throw new Exception(name);if(value is UnityEngine.Object o)p.objectReferenceValue=o;else if(value is bool b)p.boolValue=b;else if(value is int i)p.intValue=i;else if(value is float f)p.floatValue=f;so.ApplyModifiedPropertiesWithoutUndo();}
static Material Save(Material m,string name){string p=Root+name+".mat";var old=AssetDatabase.LoadAssetAtPath<Material>(p);if(old){EditorUtility.CopySerialized(m,old);UnityEngine.Object.DestroyImmediate(m);return old;}AssetDatabase.CreateAsset(m,p);return m;}
static void Schedule(string name){captureName=name;due=EditorApplication.timeSinceStartup+8;}
static void Run(string stage){Directory.CreateDirectory(Root);
if(stage=="demo"){EditorSceneManager.OpenScene("Assets/Samples/Crest/5.9.3/Main/Scenes/Main.unity");var water=UnityEngine.Object.FindFirstObjectByType<WaterRenderer>();camera=UnityEngine.Object.FindObjectsByType<Camera>(FindObjectsSortMode.None).First(c=>c.enabled&&c.cameraType==CameraType.Game);Set(water,"_Camera",camera);Set(water,"_FollowSceneCamera",false);Set(water,"_EditorMultipleViewpoints",false);camera.GetUniversalAdditionalCameraData().renderPostProcessing=true;Debug.Log("CREST LAB DEMO camera="+camera.name+" position="+camera.transform.position);Schedule("CrestDemo");return;}
var scene=EditorSceneManager.OpenScene(stage=="still"?"Assets/CityForge/Art/Environment/CrestPondStudy/CrestPondZoom0.unity":Root+"Lake"+(stage=="optics"?"Still":"Optics")+".unity");var w=UnityEngine.Object.FindFirstObjectByType<WaterRenderer>();camera=GameObject.Find("Meadow presentation camera").GetComponent<Camera>();UnityEngine.Object.DestroyImmediate(camera.GetComponent<CityForgeCameraController>());
if(stage=="still"){
var sky=new Material(AssetDatabase.LoadAssetAtPath<Material>("Assets/MapMagic/Demo/Materials/SkyCloudyEvening.mat"));sky.SetFloat("_Exposure",1f);sky.SetFloat("_Rotation",110);RenderSettings.skybox=Save(sky,"CloudySky");DynamicGI.UpdateEnvironment();
var terrain=UnityEngine.Object.FindFirstObjectByType<Terrain>(FindObjectsInactive.Include);var trees=new GameObject("Temporary shoreline reflection trees");Vector2[] positions={new Vector2(98,151),new Vector2(108,157),new Vector2(123,163),new Vector2(138,163),new Vector2(153,159),new Vector2(166,148),new Vector2(169,132)};var prefabs=AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/CityForge/Art/Environment/ForestTreesTrial"});Debug.Log("TREE PREFABS "+prefabs.Length);
for(int i=0;i<positions.Length;i++){string p=i%3==0?"Assets/CityForge/Resources/Trees/FraserFirA.prefab":AssetDatabase.GUIDToAssetPath(prefabs.First(g=>AssetDatabase.GUIDToAssetPath(g).Contains("medium_poly_"+(i%5+1)+".prefab")));var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(p);var go=(GameObject)PrefabUtility.InstantiatePrefab(prefab);go.transform.SetParent(trees.transform);var x=positions[i].x;var z=positions[i].y;go.transform.position=new Vector3(x,terrain.SampleHeight(new Vector3(x,0,z)),z);go.transform.localScale*=i%3==0?.85f:.72f;foreach(var lod in go.GetComponentsInChildren<LODGroup>())lod.ForceLOD(0);}
var m=new Material(AssetDatabase.LoadAssetAtPath<Material>("Packages/com.waveharmonic.crest/Runtime/Materials/Water.mat"));m.SetFloat("_Crest_NormalMapEnabled",0);m.SetFloat("_Crest_NormalMapScrollSpeed",0);m.SetFloat("_Crest_FoamEnabled",0);m.SetFloat("_Crest_CausticsEnabled",0);m.SetFloat("_Crest_PlanarReflectionsEnabled",1);m.SetFloat("_Crest_PlanarReflectionsIntensity",1);m.SetFloat("_Crest_PlanarReflectionsApplySmoothness",0);Set(w,"_Surface._Material",Save(m,"StillWater"));Set(w,"_FoamLod._Enabled",false);Set(w,"_Underwater._Enabled",false);Set(w,"_Meniscus._Enabled",false);
camera.transform.position=new Vector3(133,8,130)-camera.transform.forward*110;camera.orthographic=true;camera.orthographicSize=40;camera.nearClipPlane=.3f;camera.farClipPlane=450;
}else if(stage=="optics"){
