var m=new Material(AssetDatabase.LoadAssetAtPath<Material>(Root+"StillWater.mat"));m.SetColor("_Crest_Scattering",new Color(.012f,.034f,.028f,1));m.SetVector("_Crest_Absorption",new Vector4(.65f,.32f,.24f,0));m.SetFloat("_Crest_TransparencyMinimumAlpha",.03f);m.SetFloat("_Crest_Smoothness",.98f);m.SetFloat("_Crest_SmoothnessFar",.98f);m.SetFloat("_Crest_SSSEnabled",0);m.SetFloat("_Crest_Fresnel",1.8f);m.SetFloat("_Crest_Specular",.04f);Set(w,"_Surface._Material",Save(m,"Freshwater"));
