static void Compare(){if(!camera)return;var w=UnityEngine.Object.FindFirstObjectByType<WaterRenderer>();bool ortho=camera.orthographic;float fov=camera.fieldOfView, size=camera.orthographicSize;var pos=camera.transform.position;var rot=camera.transform.rotation;if(captureName=="CrestDemo"){camera.transform.position=new Vector3(0,35,-90);camera.transform.LookAt(new Vector3(0,0,0));camera.orthographicSize=45;}
else {camera.orthographicSize=40;camera.transform.position=new Vector3(133,8,130)-camera.transform.forward*110;}
Debug.Log("LAB MATERIAL "+w.Surface.Material.GetFloat("_Crest_PlanarReflectionsEnabled")+" norms "+w.Surface.Material.GetFloat("_Crest_NormalMapEnabled"));foreach(bool mode in new[]{false,true}){camera.orthographic=mode;camera.fieldOfView=40;camera.ResetProjectionMatrix();Capture(camera,captureName+(mode?"_Orthographic":"_Perspective"));DumpReflection(w,captureName+(mode?"_ReflectionOrtho":"_ReflectionPerspective"));}
camera.orthographic=ortho;camera.fieldOfView=fov;camera.orthographicSize=size;camera.transform.SetPositionAndRotation(pos,rot);camera.ResetProjectionMatrix();Debug.Log("CREST LAB COMPARE COMPLETE "+captureName);}
static void Capture(Camera c,string name){var rt=new RenderTexture(1920,1080,24);rt.Create();var prev=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(c,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();File.WriteAllBytes(Out+name+".png",t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
static void DumpReflection(WaterRenderer water,string name){var flags=BindingFlags.NonPublic|BindingFlags.Instance;var reflections=typeof(WaterRenderer).GetField("_Reflections",flags).GetValue(water);var source=(RenderTexture)reflections.GetType().GetField("_ColorTexture",flags).GetValue(reflections);if(!source){Debug.Log("CREST LAB NO REFLECTION "+name);return;}var d=source.descriptor;d.dimension=TextureDimension.Tex2D;d.volumeDepth=1;d.depthBufferBits=0;d.useMipMap=false;var rt=new RenderTexture(d);rt.Create();var prev=RenderTexture.active;try{Graphics.CopyTexture(source,0,0,rt,0,0);RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBAFloat,false,true);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();var pixels=t.GetPixels();var outTex=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);for(int i=0;i<pixels.Length;i++){var c=pixels[i];pixels[i]=new Color(Mathf.LinearToGammaSpace(c.r),Mathf.LinearToGammaSpace(c.g),Mathf.LinearToGammaSpace(c.b),1);}outTex.SetPixels(pixels);outTex.Apply();File.WriteAllBytes(Out+name+".png",outTex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);UnityEngine.Object.DestroyImmediate(outTex);}finally{RenderTexture.active=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}Debug.Log("CREST LAB REFLECTION EXPORTED "+name);}
